RESET ROLE;
INSERT INTO projects(id,user_id) VALUES(test_id(851),test_id(1)),(test_id(852),test_id(1)),(test_id(853),test_id(2));
INSERT INTO contractor_invites(project_id,invited_by,email,status,accepted_at,contractor_user_id,is_primary)
 VALUES(test_id(853),test_id(2),'2@test.example','accepted',now(),test_id(2),true);
CREATE TABLE public.test_selected_links(project_id uuid,role text,token uuid);
GRANT SELECT,INSERT ON test_selected_links TO authenticated;
SET ROLE authenticated;
SELECT set_config('test.actor',test_id(1)::text,false);
SELECT test_assert((project_team_access(test_id(851))->>'can_invite_contractor')::boolean AND NOT (project_team_access(test_id(851))->>'can_invite_additional_contractor')::boolean,'client can initially invite only its primary contractor');
INSERT INTO test_selected_links VALUES(test_id(851),'primary',(create_project_invitation_link(test_id(851),'contractor')->>'token')::uuid);
INSERT INTO test_selected_links VALUES(test_id(852),'primary',(create_project_invitation_link(test_id(852),'contractor')->>'token')::uuid);
SELECT test_refused($q$SELECT invite_project_contractor(test_id(852),'8@test.example')$q$,'contractor_invitation_pending');
SELECT test_refused($q$SELECT create_project_invitation_link(test_id(851),'client')$q$,'not_permitted');
SELECT set_config('test.actor',test_id(2)::text,false);
SELECT accept_contractor_invite((SELECT token FROM test_selected_links WHERE project_id=test_id(851) AND role='primary'));
SELECT test_assert((project_team_access(test_id(851))->>'can_invite_additional_contractor')::boolean,'primary contractor can invite another contractor');
INSERT INTO test_selected_links VALUES(test_id(851),'additional',(create_project_invitation_link(test_id(851),'contractor')->>'token')::uuid);
SELECT test_assert((SELECT NOT primary_on_acceptance AND NOT is_primary FROM contractor_invites WHERE token=(SELECT token FROM test_selected_links WHERE project_id=test_id(851) AND role='additional')),'additional link does not reserve or replace the primary role');
SELECT test_assert((create_project_invitation_link(test_id(851),'contractor')->>'token')::uuid=(SELECT token FROM test_selected_links WHERE project_id=test_id(851) AND role='additional'),'retry returns the same pending additional-contractor link');
SELECT set_config('test.actor',test_id(20)::text,false);
SELECT accept_contractor_invite((SELECT token FROM test_selected_links WHERE project_id=test_id(851) AND role='additional'));
SELECT test_assert(is_contractor_on(test_id(851),test_id(20)) AND NOT is_primary_project_contractor(test_id(851)) AND NOT is_project_client(test_id(851)),'additional claimant has construction access without primary payment or client rights');
SELECT test_assert(my_account_access()->>'role'='client','project contractor assignment preserves the claimant account role');
SELECT test_assert(NOT can_invite_project_people(test_id(851)),'additional contractor cannot generate invitations');
SELECT test_refused($q$SELECT create_project_invitation_link(test_id(851),'observer')$q$,'not_permitted');
SELECT test_refused($q$SELECT invite_project_contractor(test_id(851),'8@test.example')$q$,'not_permitted');
SELECT set_config('test.actor',test_id(8)::text,false);
SELECT test_refused($q$SELECT accept_contractor_invite((SELECT token FROM test_selected_links WHERE project_id=test_id(851) AND role='additional'))$q$,'invite_invalid');
SELECT set_config('test.actor',test_id(1)::text,false);
SELECT test_assert((project_team_access(test_id(851))->>'can_invite_additional_contractor')::boolean,'primary client can also invite additional contractors');
SELECT test_assert(NOT (invite_project_contractor(test_id(851),'8@test.example')).primary_on_acceptance,'email invitation uses the same additional role');
SELECT test_refused($q$SELECT invite_project_contractor(test_id(851),'20@test.example')$q$,'already_member');
SELECT set_config('test.actor',test_id(2)::text,false);
SELECT cancel_project_contractor_invite((SELECT id FROM contractor_invites WHERE project_id=test_id(851) AND email='8@test.example'));
SELECT test_refused($q$SELECT cancel_project_contractor_invite((SELECT id FROM contractor_invites WHERE project_id=test_id(851) AND contractor_user_id=test_id(20)))$q$,'role_change_requires_admin');
INSERT INTO test_selected_links VALUES(test_id(853),'client',(create_project_invitation_link(test_id(853),'client')->>'token')::uuid);
INSERT INTO test_selected_links VALUES(test_id(853),'observer',(create_project_invitation_link(test_id(853),'observer')->>'token')::uuid);
INSERT INTO test_selected_links VALUES(test_id(853),'additional',(create_project_invitation_link(test_id(853),'contractor')->>'token')::uuid);
SELECT test_assert((SELECT count(DISTINCT token)=3 FROM test_selected_links WHERE project_id=test_id(853)),'each selected project role has a different token');
SELECT set_config('test.actor',test_id(8)::text,false);
SELECT accept_project_viewer((SELECT token FROM test_selected_links WHERE project_id=test_id(853) AND role='observer'));
SELECT test_assert(NOT is_project_client(test_id(853)) AND NOT is_contractor_on(test_id(853),test_id(8)),'observer claim cannot select client or contractor privileges');
SELECT test_refused($q$SELECT create_project_invitation_link(test_id(853),'contractor')$q$,'not_permitted');
RESET ROLE;
-- Previously issued email invitations cannot change an existing project role.
INSERT INTO projects(id,user_id) VALUES(test_id(854),test_id(1));
INSERT INTO contractor_invites(project_id,invited_by,email,status,accepted_at,contractor_user_id,is_primary)
 VALUES(test_id(854),test_id(1),'2@test.example','accepted',now(),test_id(2),true);
SET ROLE authenticated;
SELECT set_config('test.actor',test_id(1)::text,false);
SELECT invite_project_contractor(test_id(854),'21@test.example');
SELECT invite_project_viewer(test_id(854),'21@test.example',NULL,false);
SELECT invite_project_viewer(test_id(854),'22@test.example',NULL,false);
SELECT test_refused($q$SELECT invite_project_contractor(test_id(854),'22@test.example')$q$,'invitation_pending');
SELECT set_config('test.actor',test_id(21)::text,false);
SELECT accept_project_viewer((SELECT token FROM project_viewers WHERE project_id=test_id(854) AND email='21@test.example'));
SELECT test_refused($q$SELECT accept_contractor_invite((SELECT token FROM contractor_invites WHERE project_id=test_id(854) AND email='21@test.example'))$q$,'already_member');
SELECT test_assert(NOT is_contractor_on(test_id(854),test_id(21)),'an existing observer cannot claim a different role through an older email invitation');
RESET ROLE;
SELECT test_assert((SELECT count(*)=1 AND bool_and(contractor_user_id=test_id(2)) FROM contractor_invites WHERE project_id=test_id(851) AND is_primary),'original primary contractor is retained');
SELECT test_assert((SELECT bool_and(budget_amount=141407337.524) FROM projects WHERE id IN(test_id(851),test_id(852),test_id(853))),'role selection leaves project amounts unchanged');
SELECT 'INVITATION_SELECTION_OK' AS result;
